CREATE TABLE pay_periods (id BIGSERIAL PRIMARY KEY,start_date DATE NOT NULL,end_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',pay_date DATE NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uk_pay_period_dates UNIQUE(start_date,end_date));
CREATE TABLE payroll_records (id BIGSERIAL PRIMARY KEY,pay_period_id BIGINT NOT NULL REFERENCES pay_periods(id),employee_id BIGINT NOT NULL,regular_hours NUMERIC(10,2) NOT NULL,overtime_hours NUMERIC(10,2) NOT NULL,gross_pay NUMERIC(19,2) NOT NULL,net_pay NUMERIC(19,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uk_payroll_period_employee UNIQUE(pay_period_id,employee_id));
CREATE INDEX idx_payroll_employee ON payroll_records(employee_id);
CREATE TABLE payroll_earnings (id BIGSERIAL PRIMARY KEY,payroll_record_id BIGINT NOT NULL REFERENCES payroll_records(id),type VARCHAR(20) NOT NULL,amount NUMERIC(19,2) NOT NULL,description VARCHAR(250),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_earning_record ON payroll_earnings(payroll_record_id);
CREATE TABLE payroll_deductions (id BIGSERIAL PRIMARY KEY,payroll_record_id BIGINT NOT NULL REFERENCES payroll_records(id),type VARCHAR(20) NOT NULL,amount NUMERIC(19,2) NOT NULL,description VARCHAR(250),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_deduction_record ON payroll_deductions(payroll_record_id);
